CREATE TABLE IF NOT EXISTS job_requirement_location (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  country_id UUID NOT NULL,
  state_region_id UUID,
  city_id UUID,
  organisation_location_id UUID,
  address_line STRING(300),
  is_primary BOOL NOT NULL DEFAULT false,
  latitude DECIMAL(9,6),
  longitude DECIMAL(9,6),
  geo_source_id UUID,
  CONSTRAINT pk_job_requirement_location PRIMARY KEY (id),
  CONSTRAINT ck_job_requirement_location_latitude_range CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CONSTRAINT ck_job_requirement_location_longitude_range CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
  CONSTRAINT ck_job_requirement_location_coordinates_pair CHECK ((latitude IS NULL) = (longitude IS NULL)),
  CONSTRAINT ck_job_requirement_location_coordinate_source CHECK (latitude IS NULL OR geo_source_id IS NOT NULL),
  CONSTRAINT fk_job_requirement_location_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_requirement_location_country_id FOREIGN KEY (country_id) REFERENCES country (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_requirement_location_state_region_id FOREIGN KEY (state_region_id) REFERENCES state_region (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_requirement_location_city_id FOREIGN KEY (city_id) REFERENCES city (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_requirement_location_organisation_location_id FOREIGN KEY (organisation_location_id) REFERENCES organisation_location (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_job_requirement_location_geo_source_id FOREIGN KEY (geo_source_id) REFERENCES geo_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_job_requirement_location_job_requirement_id (job_requirement_id),
  UNIQUE INDEX uq_job_requirement_location_job_requirement_id_primary (job_requirement_id) WHERE is_primary,
  INDEX idx_job_requirement_location_city_id_job_requirement_id (city_id, job_requirement_id) WHERE city_id IS NOT NULL,
  INDEX idx_job_requirement_location_organisation_location_id (organisation_location_id) WHERE organisation_location_id IS NOT NULL
);
