  cost_amount DECIMAL(18,4),
  currency_id UUID,
  CONSTRAINT pk_job_syndication PRIMARY KEY (id),
  CONSTRAINT ck_job_syndication_removed_after_posted CHECK (removed_at IS NULL OR posted_at IS NULL OR removed_at >= posted_at),
  CONSTRAINT ck_job_syndication_cost_companion CHECK (cost_amount IS NULL OR currency_id IS NOT NULL),
  CONSTRAINT fk_job_syndication_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_syndication_job_posting_channel_id FOREIGN KEY (job_posting_channel_id) REFERENCES job_posting_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_syndication_syndication_status_id FOREIGN KEY (syndication_status_id) REFERENCES syndication_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_syndication_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_job_syndication_job_requirement_id_channel (job_requirement_id, job_posting_channel_id) WHERE deleted_at IS NULL,
  UNIQUE INDEX uq_job_syndication_job_posting_channel_id_external_posting_ref (job_posting_channel_id, external_posting_ref) WHERE external_posting_ref IS NOT NULL AND deleted_at IS NULL,
  INDEX idx_job_syndication_syndication_status_id_last_synced_at (syndication_status_id, last_synced_at) WHERE syndication_status_id IS NOT NULL
);
