  valid_to TIMESTAMPTZ,
  commission_percent DECIMAL(5,2),
  flat_fee_amount DECIMAL(18,4),
  currency_id UUID,
  max_consultants INT2,
  guarantee_days INT2,
  CONSTRAINT pk_job_consultant_openness PRIMARY KEY (id),
  CONSTRAINT ck_job_consultant_openness_valid_range CHECK (valid_to IS NULL OR valid_to >= valid_from),
  CONSTRAINT ck_job_consultant_openness_commission_percent_range CHECK (commission_percent IS NULL OR (commission_percent >= 0 AND commission_percent <= 100)),
  CONSTRAINT ck_job_consultant_openness_fee_companions CHECK (flat_fee_amount IS NULL OR currency_id IS NOT NULL),
  CONSTRAINT ck_job_consultant_openness_max_consultants_pos CHECK (max_consultants IS NULL OR max_consultants > 0),
  CONSTRAINT fk_job_consultant_openness_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_consultant_openness_consultant_access_scope_id FOREIGN KEY (consultant_access_scope_id) REFERENCES consultant_access_scope (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_consultant_openness_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_job_consultant_openness_job_requirement_id_valid_from (job_requirement_id, valid_from DESC),
  UNIQUE INDEX uq_job_consultant_openness_job_requirement_id_open (job_requirement_id) WHERE valid_to IS NULL AND deleted_at IS NULL
);
