CREATE TABLE IF NOT EXISTS interview (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  job_application_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  interview_panel_id UUID,
  round_no INT2 NOT NULL,
  interview_round_type_id UUID NOT NULL,
  interview_mode_id UUID NOT NULL,
  interview_status_id UUID NOT NULL,
  scheduled_start_at TIMESTAMPTZ NOT NULL,
  scheduled_end_at TIMESTAMPTZ NOT NULL,
  time_zone STRING(64) NOT NULL,
  meeting_url STRING(500),
  location_text STRING(300),
  organisation_location_id UUID,
  candidate_confirmed_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  cancelled_at TIMESTAMPTZ,
  cancelled_by_actor_kind_id UUID,
  cancel_reason STRING(300),
  overall_interview_recommendation_id UUID,
  CONSTRAINT pk_interview PRIMARY KEY (id),
  CONSTRAINT uq_interview_id_job_application_id UNIQUE (id, job_application_id),
  CONSTRAINT ck_interview_schedule_range CHECK (scheduled_end_at > scheduled_start_at),
  CONSTRAINT ck_interview_max_duration CHECK (scheduled_end_at <= scheduled_start_at + INTERVAL '12 hours'),
  CONSTRAINT ck_interview_round_pos CHECK (round_no >= 1),
  CONSTRAINT ck_interview_cancel_consistency CHECK ((cancelled_at IS NULL) = (cancelled_by_actor_kind_id IS NULL)),
  CONSTRAINT fk_interview_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_panel FOREIGN KEY (interview_panel_id, organisation_id) REFERENCES interview_panel (id, organisation_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_interview_round_type_id FOREIGN KEY (interview_round_type_id) REFERENCES interview_round_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_interview_mode_id FOREIGN KEY (interview_mode_id) REFERENCES interview_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_interview_status_id FOREIGN KEY (interview_status_id) REFERENCES interview_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_organisation_location_id FOREIGN KEY (organisation_location_id) REFERENCES organisation_location (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_cancelled_by_actor_kind_id FOREIGN KEY (cancelled_by_actor_kind_id) REFERENCES actor_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_overall_interview_recommendation_id FOREIGN KEY (overall_interview_recommendation_id) REFERENCES interview_recommendation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_interview_job_application_id_round_no (job_application_id, round_no) WHERE deleted_at IS NULL AND cancelled_at IS NULL,
  INDEX idx_interview_job_requirement_id_scheduled_start_at (job_requirement_id, scheduled_start_at),
  INDEX idx_interview_organisation_id_scheduled_start_at (organisation_id, scheduled_start_at DESC) STORING (job_application_id, interview_status_id) WHERE cancelled_at IS NULL,
  INDEX idx_interview_scheduled_start_at_hash (scheduled_start_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_interview_interview_panel_id (interview_panel_id) WHERE interview_panel_id IS NOT NULL,
  INDEX idx_interview_organisation_location_id (organisation_location_id) WHERE organisation_location_id IS NOT NULL
);
