  CONSTRAINT ck_interview_reschedule_new_range CHECK (new_end_at > new_start_at),
  CONSTRAINT fk_interview_reschedule_interview_id FOREIGN KEY (interview_id) REFERENCES interview (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_interview_reschedule_requested_by_actor_kind_id FOREIGN KEY (requested_by_actor_kind_id) REFERENCES actor_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
