CREATE TABLE IF NOT EXISTS job_application (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  candidate_profile_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  job_position_id UUID,
  job_source_id UUID NOT NULL,
  application_status_id UUID NOT NULL,
  status_sequence_no INT4 NOT NULL DEFAULT 1,
  status_changed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  resume_id UUID,
  candidate_message STRING(2000),
  expected_salary_amount DECIMAL(18,4),
  currency_id UUID,
  salary_period_id UUID,
  notice_period_days INT2,
  match_score DECIMAL(5,2),
  screening_score DECIMAL(5,2),
  is_screened_out BOOL NOT NULL DEFAULT false,
  submitted_by_app_user_id UUID,
  first_viewed_at TIMESTAMPTZ,
  withdrawn_at TIMESTAMPTZ,
  withdrawal_reason_id UUID,
  CONSTRAINT pk_job_application PRIMARY KEY (id),
  CONSTRAINT uq_job_application_id_job_requirement_id UNIQUE (id, job_requirement_id),
  CONSTRAINT ck_job_application_match_score_range CHECK (match_score IS NULL OR (match_score >= 0 AND match_score <= 100)),
  CONSTRAINT ck_job_application_screening_score_range CHECK (screening_score IS NULL OR (screening_score >= 0 AND screening_score <= 100)),
  CONSTRAINT ck_job_application_salary_companions CHECK (expected_salary_amount IS NULL OR (currency_id IS NOT NULL AND salary_period_id IS NOT NULL AND expected_salary_amount >= 0)),
  CONSTRAINT ck_job_application_notice_period_range CHECK (notice_period_days IS NULL OR (notice_period_days >= 0 AND notice_period_days <= 365)),
  CONSTRAINT ck_job_application_withdrawn_reason_requires_withdrawn CHECK (withdrawn_at IS NOT NULL OR withdrawal_reason_id IS NULL),
  CONSTRAINT ck_job_application_status_sequence_pos CHECK (status_sequence_no >= 1),
  CONSTRAINT ck_job_application_viewed_after_applied CHECK (first_viewed_at IS NULL OR first_viewed_at >= applied_at),
  CONSTRAINT ck_job_application_withdrawn_after_applied CHECK (withdrawn_at IS NULL OR withdrawn_at >= applied_at),
  CONSTRAINT fk_job_application_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_requirement FOREIGN KEY (organisation_id, job_requirement_id) REFERENCES job_requirement (organisation_id, id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_job_source_id FOREIGN KEY (job_source_id) REFERENCES job_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_application_status_id FOREIGN KEY (application_status_id) REFERENCES application_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_resume_id FOREIGN KEY (resume_id) REFERENCES resume (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_salary_period_id FOREIGN KEY (salary_period_id) REFERENCES salary_period (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_submitted_by_app_user_id FOREIGN KEY (submitted_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_withdrawal_reason_id FOREIGN KEY (withdrawal_reason_id) REFERENCES withdrawal_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_job_application_candidate_profile_id_job_requirement_id (candidate_profile_id, job_requirement_id) WHERE withdrawn_at IS NULL AND deleted_at IS NULL,
  INDEX idx_job_application_job_requirement_id_status_applied (job_requirement_id, application_status_id, applied_at DESC) STORING (candidate_profile_id, match_score),
  INDEX idx_job_application_candidate_profile_id_applied_at (candidate_profile_id, applied_at DESC) STORING (application_status_id, job_requirement_id),
  INDEX idx_job_application_organisation_id_application_status_id_status_changed_at (organisation_id, application_status_id, status_changed_at DESC),
  INDEX idx_job_application_applied_at_hash (applied_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_job_application_status_changed_at_hash (status_changed_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_job_application_resume_id (resume_id) WHERE resume_id IS NOT NULL,
  INDEX idx_job_application_submitted_by_app_user_id_applied_at (submitted_by_app_user_id, applied_at DESC) WHERE submitted_by_app_user_id IS NOT NULL
);
