CREATE TABLE IF NOT EXISTS job_application_document (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  job_application_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  document_type_id UUID NOT NULL,
  file_name STRING(255) NOT NULL,
  storage_url STRING(500) NOT NULL,
  mime_type STRING(100) NOT NULL,
  file_size_bytes INT8 NOT NULL,
  content_sha256 STRING(64) NOT NULL,
  CONSTRAINT pk_job_application_document PRIMARY KEY (id),
  CONSTRAINT ck_job_application_document_size_pos CHECK (file_size_bytes > 0 AND file_size_bytes <= 26214400),
  CONSTRAINT ck_job_application_document_sha256_format CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
  CONSTRAINT fk_job_application_document_application FOREIGN KEY (job_application_id, job_requirement_id) REFERENCES job_application (id, job_requirement_id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_document_document_type_id FOREIGN KEY (document_type_id) REFERENCES document_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_job_application_document_job_application_id (job_application_id),
  INDEX idx_job_application_document_job_requirement_id (job_requirement_id)
