CREATE TABLE IF NOT EXISTS job_application_status_history (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  job_application_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  sequence_no INT4 NOT NULL,
  prior_sequence_no INT4,
  from_application_status_id UUID,
  to_application_status_id UUID NOT NULL,
  actor_kind_id UUID NOT NULL,
  rejection_reason_id UUID,
  comment_text STRING(1000),
  idempotency_key STRING(100),
  CONSTRAINT pk_job_application_status_history PRIMARY KEY (id),
  CONSTRAINT uq_job_application_status_history_job_application_id_sequence_no UNIQUE (job_application_id, sequence_no),
  CONSTRAINT uq_job_application_status_history_job_application_id_sequence_no_to_application_status_id UNIQUE (job_application_id, sequence_no, to_application_status_id),
  CONSTRAINT ck_job_application_status_history_first_row CHECK ((prior_sequence_no IS NULL) = (sequence_no = 1)),
  CONSTRAINT ck_job_application_status_history_prior_adjacent CHECK (prior_sequence_no IS NULL OR prior_sequence_no = sequence_no - 1),
  CONSTRAINT ck_job_application_status_history_from_null_iff_first CHECK ((from_application_status_id IS NULL) = (prior_sequence_no IS NULL)),
  CONSTRAINT ck_job_application_status_history_distinct_states CHECK (from_application_status_id IS NULL OR from_application_status_id <> to_application_status_id),
  CONSTRAINT fk_job_application_status_history_application FOREIGN KEY (job_application_id, job_requirement_id) REFERENCES job_application (id, job_requirement_id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_status_history_chain FOREIGN KEY (job_application_id, prior_sequence_no, from_application_status_id) REFERENCES job_application_status_history (job_application_id, sequence_no, to_application_status_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_status_history_transition FOREIGN KEY (from_application_status_id, to_application_status_id) REFERENCES application_status_transition (from_application_status_id, to_application_status_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_status_history_to_application_status_id FOREIGN KEY (to_application_status_id) REFERENCES application_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_status_history_actor_kind_id FOREIGN KEY (actor_kind_id) REFERENCES actor_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_job_application_status_history_rejection_reason_id FOREIGN KEY (rejection_reason_id) REFERENCES rejection_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_job_application_status_history_created_at_hash (created_at) USING HASH WITH (bucket_count = 32),
  INDEX idx_job_application_status_history_job_requirement_id_funnel (job_requirement_id, to_application_status_id, created_at),
  UNIQUE INDEX uq_job_application_status_history_idempotency_key (idempotency_key) WHERE idempotency_key IS NOT NULL
);
