CREATE TABLE IF NOT EXISTS offer (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  job_application_id UUID NOT NULL,
  job_requirement_id UUID NOT NULL,
  organisation_id UUID NOT NULL,
  offer_status_id UUID NOT NULL,
  is_open BOOL NOT NULL DEFAULT true,
  current_revision_no INT4,
  sent_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  responded_at TIMESTAMPTZ,
  offer_decline_reason_id UUID,
  proposed_joining_date DATE,
  approved_at TIMESTAMPTZ,
  CONSTRAINT pk_offer PRIMARY KEY (id),
  CONSTRAINT uq_offer_id_job_application_id UNIQUE (id, job_application_id),
  CONSTRAINT ck_offer_expiry_after_sent CHECK (expires_at IS NULL OR sent_at IS NULL OR expires_at > sent_at),
  CONSTRAINT ck_offer_response_after_sent CHECK (responded_at IS NULL OR sent_at IS NULL OR responded_at >= sent_at),
  CONSTRAINT ck_offer_decline_reason_requires_response CHECK (offer_decline_reason_id IS NULL OR responded_at IS NOT NULL),
  CONSTRAINT fk_offer_application FOREIGN KEY (job_application_id, job_requirement_id) REFERENCES job_application (id, job_requirement_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_offer_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_offer_offer_status_id FOREIGN KEY (offer_status_id) REFERENCES offer_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_offer_offer_decline_reason_id FOREIGN KEY (offer_decline_reason_id) REFERENCES offer_decline_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_offer_job_application_id_open (job_application_id) WHERE is_open AND deleted_at IS NULL,
  INDEX idx_offer_organisation_id_offer_status_id_sent_at (organisation_id, offer_status_id, sent_at DESC),
  INDEX idx_offer_job_requirement_id_offer_status_id (job_requirement_id, offer_status_id),
  INDEX idx_offer_expires_at (expires_at) WHERE is_open AND expires_at IS NOT NULL
);
