  rejected_from_application_status_id UUID NOT NULL,
  rejected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  internal_comment STRING(1000),
  candidate_message STRING(1000),
  notify_candidate BOOL NOT NULL DEFAULT true,
  reinstated_at TIMESTAMPTZ,
  CONSTRAINT pk_rejection PRIMARY KEY (id),
  CONSTRAINT ck_rejection_reinstated_after_rejected CHECK (reinstated_at IS NULL OR reinstated_at >= rejected_at),
  CONSTRAINT fk_rejection_application FOREIGN KEY (job_application_id, job_requirement_id) REFERENCES job_application (id, job_requirement_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_rejection_rejection_reason_id FOREIGN KEY (rejection_reason_id) REFERENCES rejection_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_rejection_rejected_from_application_status_id FOREIGN KEY (rejected_from_application_status_id) REFERENCES application_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_rejection_job_application_id_active (job_application_id) WHERE reinstated_at IS NULL AND deleted_at IS NULL,
  INDEX idx_rejection_job_requirement_id_rejection_reason_id (job_requirement_id, rejection_reason_id)
);
-- @@
CREATE TABLE IF NOT EXISTS talent_pool_member (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  talent_pool_id UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  source_job_application_id UUID,
  tags STRING(200),
  retain_until_date DATE,
  CONSTRAINT pk_talent_pool_member PRIMARY KEY (id),
  CONSTRAINT uq_talent_pool_member_talent_pool_id_candidate_profile_id UNIQUE (talent_pool_id, candidate_profile_id),
  CONSTRAINT fk_talent_pool_member_talent_pool_id FOREIGN KEY (talent_pool_id) REFERENCES talent_pool (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_talent_pool_member_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_talent_pool_member_source_job_application_id FOREIGN KEY (source_job_application_id) REFERENCES job_application (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  INDEX idx_talent_pool_member_candidate_profile_id (candidate_profile_id),
  INDEX idx_talent_pool_member_retain_until_date (retain_until_date) WHERE retain_until_date IS NOT NULL,
  INDEX idx_talent_pool_member_source_job_application_id (source_job_application_id) WHERE source_job_application_id IS NOT NULL
);
